import{_ as a,o as e,c as n,ap as t}from"./chunks/framework.CuFS6FqL.js";const u=JSON.parse('{"title":"YubiKey PC setup","description":"Configure a PC to use an already provisioned YubiKey for PIV/SSH (Windows) and basic GPG/SSH agent use.","frontmatter":{"title":"YubiKey PC setup","description":"Configure a PC to use an already provisioned YubiKey for PIV/SSH (Windows) and basic GPG/SSH agent use."},"headers":[],"relativePath":"organization/human-resources/yubikey-pc-setup.md","filePath":"organization/human-resources/yubikey-pc-setup.md"}'),i={name:"organization/human-resources/yubikey-pc-setup.md"};function o(p,s,l,r,c,d){return e(),n("div",null,[...s[0]||(s[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/human-resources/yubikey-pc-setup.md for this page in Markdown format</div><h1 id="yubikey-pc-setup" tabindex="-1">YubiKey PC setup <a class="header-anchor" href="#yubikey-pc-setup" aria-label="Permalink to &quot;YubiKey PC setup&quot;">​</a></h1><p>Do this on every PC you use with your YubiKey (for example after getting a new machine). The key itself must already be provisioned: <a href="./yubikey-setup">YubiKey setup</a>.</p><h2 id="piv" tabindex="-1">PIV <a class="header-anchor" href="#piv" aria-label="Permalink to &quot;PIV&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>Prerequisites:</p><ul><li>Install <a href="https://github.com/OpenSC/OpenSC/releases/latest" target="_blank" rel="noreferrer">OpenSC Library for PKCS11</a> (<a href="https://github.com/OpenSC/OpenSC/wiki" target="_blank" rel="noreferrer">Documentation</a>)</li><li>Install <a href="https://github.com/Yubico/yubikey-manager/releases/latest" target="_blank" rel="noreferrer">YubiKey Manager CLI</a></li><li>Yubico Authenticator</li><li>Have your PIN ready (stored in Vaultwarden)</li><li>Make sure OpenSC ignores Windows Hello (see <a href="#troubleshooting">Troubleshooting</a> below)</li></ul><ol><li>Connect with ssh:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh -I &quot;C:\\Program Files\\OpenSC Project\\OpenSC\\pkcs11\\opensc-pkcs11.dll&quot; user@IP</span></span></code></pre></div><ol start="2"><li>(Recommended) Add to your <code>~\\.ssh\\config</code> (create file if it doesn&#39;t exist):</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PKCS11Provider &quot;C:\\Program Files\\Yubico\\Yubico PIV Tool\\bin\\libykcs11.dll&quot;</span></span></code></pre></div><h4 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h4><h5 id="windows-hello" tabindex="-1">Windows Hello <a class="header-anchor" href="#windows-hello" aria-label="Permalink to &quot;Windows Hello&quot;">​</a></h5><p>It is possible that OpenSC recognizes &quot;Windows Hello&quot; as its own device, thus you extract its RSA key. To prevent this, modify <code>C:\\Program Files\\OpenSC Project\\OpenSC\\opensc.conf</code> to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app default {</span></span>
<span class="line"><span>	# debug = 3;</span></span>
<span class="line"><span>	# debug_file = opensc-debug.txt;</span></span>
<span class="line"><span>	ignored_readers = &quot;Windows Hello&quot; ; # Ignore all readers containing &quot;Windows Hello&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>To list all devices, run <code>&amp; &quot;C:\\Program Files\\OpenSC Project\\OpenSC\\tools\\opensc-tool.exe&quot; --list-readers</code> (PowerShell).</p><h5 id="error-signing-failed-for-rsa-priv-auth-pubkey-error-in-libcrypto" tabindex="-1">Error: signing failed for RSA &quot;PRIV AUTH pubkey: error in libcrypto&quot; <a class="header-anchor" href="#error-signing-failed-for-rsa-priv-auth-pubkey-error-in-libcrypto" aria-label="Permalink to &quot;Error: signing failed for RSA &quot;PRIV AUTH pubkey: error in libcrypto&quot;&quot;">​</a></h5><p>Don&#39;t forget to touch your key when authenticating. If that does not help, the key may use an unsupported algorithm. See <a href="./yubikey-setup#supported-algorithms">Supported algorithms</a> on the initial setup page.</p><h4 id="agent-forwarding" tabindex="-1">Agent forwarding <a class="header-anchor" href="#agent-forwarding" aria-label="Permalink to &quot;Agent forwarding&quot;">​</a></h4><p>You can forward the YubiKey&#39;s authentication capabilities to the remote server, so that you can use this server as a jump host to another remote destination.<br> A classic example is developing on a remote machine and using SSH to push the changes to GitLab.</p><p>Your YubiKey must have been created with <code>pin-policy</code> set to <code>once</code> (not <code>always</code>). That is set during <a href="./yubikey-setup">initial setup</a> and cannot be changed afterwards.</p><p>To enable agent forwarding you must load your SSH key into your agent using:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ssh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">add </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:\\Program Files\\Yubico\\Yubico PIV Tool\\bin\\libykcs11.dll&quot;</span></span></code></pre></div><p>You can check if this was successfull using <code>ssh-add -L</code> and, if necessary, clear the key using <code>ssh-add -D</code>.</p><p>Your client must know to which remote hosts it should forward the agent. Use <code>ssh -A user@ip</code> to forward the agent.<br> You can optionally add <code>ForwardAgent yes</code> to your <code>~\\.ssh\\config</code>, e.g.:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host alias1 alias2</span></span>
<span class="line"><span>    HostName HostOrIp</span></span>
<span class="line"><span>    PKCS11Provider &quot;C:\\Program Files\\OpenSC Project\\OpenSC\\pkcs11\\opensc-pkcs11.dll&quot;</span></span>
<span class="line"><span>    User username</span></span>
<span class="line"><span>    ForwardAgent yes</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Don&#39;t forward the agent to all destinations. Only to destinations where needed.</p></div><p>Now the remote host also needs to accept your forwarded agent. Add <code>AllowAgentForwarding yes</code> to <code>/etc/ssh/sshd_config</code> on the remote host.<br> Reconnect and check if the agent was forwarded:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-rsa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AAAAB...</span></span></code></pre></div><p>Your agent was forwarded successfully. You can now connect to other destinations from there. 🍵</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>TODO<br> See also: <a href="https://github.com/pavel-odintsov/yubikey-ssh" target="_blank" rel="noreferrer">YubiKey SSH guide</a></p><h2 id="gpg" tabindex="-1">GPG <a class="header-anchor" href="#gpg" aria-label="Permalink to &quot;GPG&quot;">​</a></h2><h3 id="windows-1" tabindex="-1">Windows <a class="header-anchor" href="#windows-1" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><h4 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h4><ol><li><p>Install gpg4win (Download here: <a href="https://gpg4win.org/download.html" target="_blank" rel="noreferrer">gpg4win</a>)</p></li><li><p>After installing gpg4win you need to edit <code>C:\\Users\\&lt;user&gt;\\AppData\\Roaming\\gnupg\\gpg-agent.conf</code> and add following content:</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enable-ssh-support</span></span>
<span class="line"><span>enable-putty-support</span></span>
<span class="line"><span>enable-win32-openssh-support</span></span>
<span class="line"><span>use-standard-socket</span></span>
<span class="line"><span>default-cache-ttl 600</span></span>
<span class="line"><span>max-cache-ttl 7200</span></span></code></pre></div><ol start="3"><li>Restart the gpg-connect-agent:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gpg-connect-agent killagent /bye</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gpg-connect-agent /bye</span></span></code></pre></div><ol start="4"><li>Create a startup script to restart the agent after every login.<br> The script must be placed under <code>C:\\Users\\&lt;user&gt;\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup</code>.<br> Startup script: <a href="/assets/gpg-agent-login.cmd">gpg-agent-login.cmd</a></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@echo off</span></span>
<span class="line"><span>REM Runs after every Windows login.</span></span>
<span class="line"><span>REM Restarts gpg-agent: kill the old one, then start a fresh one.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set &quot;GPG_CONNECT=C:\\Program Files\\GnuPG\\bin\\gpg-connect-agent.exe&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REM Give the user session a moment to finish starting.</span></span>
<span class="line"><span>timeout /t 3 /nobreak &gt;nul</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;%GPG_CONNECT%&quot; killagent /bye</span></span>
<span class="line"><span>&quot;%GPG_CONNECT%&quot; /bye</span></span></code></pre></div><h4 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h4><ul><li><p><strong>Cloning repositories using SSH-Keys</strong></p><p>The error message &quot;<code>git@ssh.gitlab.internal.syslifters.com: Permission denied (publickey).</code>&quot;<br> most likely indicates that Git is using a different ssh command to clone the repo. However, verify first if authentication with the SSH-Key works.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh -T git@ssh.gitlab.internal.syslifters.com</span></span></code></pre></div><p>If the server returns no errors, your authentication with a SSH-Key is working correctly. Overwrite the <code>core.sshCommand</code> setting for git:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git config --global core.sshCommand &quot;C:/Windows/System32/OpenSSH/ssh.exe&quot;</span></span></code></pre></div></li></ul><h3 id="linux-1" tabindex="-1">Linux <a class="header-anchor" href="#linux-1" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>Setup only.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install -y \\</span></span>
<span class="line"><span>  gnupg2 \\</span></span>
<span class="line"><span>  gnupg-agent \\</span></span>
<span class="line"><span>  scdaemon \\</span></span>
<span class="line"><span>  pcscd \\</span></span>
<span class="line"><span>  pcsc-tools \\</span></span>
<span class="line"><span>  yubikey-personalization</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo systemctl enable --now pcscd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>~/.gnupg/gpg-agent.conf</span></span>
<span class="line"><span>enable-ssh-support</span></span>
<span class="line"><span>default-cache-ttl 600</span></span>
<span class="line"><span>max-cache-ttl 7200</span></span>
<span class="line"><span>pinentry-program /usr/bin/pinentry-gnome3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>gpgconf --kill gpg-agent</span></span>
<span class="line"><span></span></span>
<span class="line"><span>in .bashrc /.zshrc</span></span>
<span class="line"><span>export SSH_AUTH_SOCK=$(gpgconf --list-dirs agent-ssh-socket)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>gpgconf --launch gpg-agent</span></span></code></pre></div>`,47)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
